def self.copy(sym, *syms)
  @@formSpecies.copy(sym, *syms)
end

def self.register(sym, hash)
  @@formSpecies.add(sym, hash)
end

def self.registerIf(sym, cond, hash)
  @@formSpecies.addIf(sym, cond, hash)
end

def self.call(func, pkmn, *args)
  sp = @@formSpecies[pkmn.species]
  return nil if !sp || !sp[func]
  return sp[func].call(pkmn, *args)
end

def form=(value)
  oldForm = @form
  @form = value
  @ability = nil
  MultipleForms.call("onSetForm", self, value, oldForm)
  calc_stats
  $player&.pokedex&.register(self)
end

def setForm(value)
  oldForm = @form
  @form = value
  @ability = nil
  yield if block_given?
  MultipleForms.call("onSetForm", self, value, oldForm)
  calc_stats
  $player&.pokedex&.register(self)
end

def form_simple=(value)
  @form = value
  calc_stats
end

def initialize(species, level, owner = $player, withMoves = true, recheck_form = true)
  species_data = GameData::Species.get(species)
  @species          = species_data.species
  @form             = species_data.base_form
  @forced_form      = nil
  @time_form_set    = nil
  self.level        = level
  @steps_to_hatch   = 0
  heal_status
  @gender           = nil
  @shiny            = nil
  @ability_index    = nil
  @ability          = nil
  @nature           = nil
  @nature_for_stats = nil
  @item             = nil
  @mail             = nil
  @moves            = []
  reset_moves if withMoves
  @first_moves      = []
  @ribbons          = []
  @cool             = 0
  @beauty           = 0
  @cute             = 0
  @smart            = 0
  @tough            = 0
  @sheen            = 0
  @pokerus          = 0
  @name             = nil
  @happiness        = species_data.happiness
  @poke_ball        = :POKEBALL
  @markings         = []
  @iv               = {}
  @ivMaxed          = {}
  @ev               = {}
  GameData::Stat.each_main do |s|
    @iv[s.id]       = rand(IV_STAT_LIMIT + 1)
    @ev[s.id]       = 0
  end
  case owner
  when Owner
    @owner = owner
  when Player, NPCTrainer
    @owner = Owner.new_from_trainer(owner)
  else
    @owner = Owner.new(0, "", 2, 2)
  end
  @obtain_method    = 0   # Met
  @obtain_method    = 4 if $game_switches && $game_switches[Settings::FATEFUL_ENCOUNTER_SWITCH]
  @obtain_map       = ($game_map) ? $game_map.map_id : 0
  @obtain_text      = nil
  @obtain_level     = level
  @hatched_map      = 0
  @timeReceived     = Time.now.to_i
  @timeEggHatched   = nil
  @fused            = nil
  @personalID       = rand(2**16) | (rand(2**16) << 16)
  @hp               = 1
  @totalhp          = 1
  calc_stats
  if @form == 0 && recheck_form
    f = MultipleForms.call("getFormOnCreation", self)
    if f
      self.form = f
      reset_moves if withMoves
    end
  end
end

def self.sprite_bitmap(species, form = 0, gender = 0, shiny = false, shadow = false, back = false, egg = false)
  return self.egg_sprite_bitmap(species, form) if egg
  return self.back_sprite_bitmap(species, form, gender, shiny, shadow) if back
  return self.front_sprite_bitmap(species, form, gender, shiny, shadow)
end

def self.icon_filename_from_pokemon(pkmn)
  return self.icon_filename(pkmn.species, pkmn.form, pkmn.gender, pkmn.shiny?, pkmn.shadowPokemon?, pkmn.egg?)
end

def id=(value)
  @id = GameData::Move.get(value).id
  @pp = @pp.clamp(0, total_pp)
end

class HandlerHashSymbol
  def initialize
    @hash    = {}
    @add_ifs = {}
  end

  def [](sym)
    sym = sym.id if !sym.is_a?(Symbol) && sym.respond_to?("id")
    return @hash[sym] if sym && @hash[sym]
    @add_ifs.each_value do |add_if|
      return add_if[1] if add_if[0].call(sym)
    end
    return nil
  end

  def add(sym, handler = nil, &handlerBlock)
    if ![Proc, Hash].include?(handler.class) && !block_given?
      raise ArgumentError, "#{self.class.name} for #{sym.inspect} has no valid handler (#{handler.inspect} was given)"
    end
    @hash[sym] = handler || handlerBlock if sym
  end

  def addIf(sym, conditionProc, handler = nil, &handlerBlock)
    if ![Proc, Hash].include?(handler.class) && !block_given?
      raise ArgumentError, "addIf call for #{sym} in #{self.class.name} has no valid handler (#{handler.inspect} was given)"
    end
    @add_ifs[sym] = [conditionProc, handler || handlerBlock]
  end

  def copy(src, *dests)
    handler = self[src]
    return if !handler
    dests.each { |dest| add(dest, handler) }
  end

  def remove(key)
    @hash.delete(key)
  end

  def clear
    @hash.clear
    @add_ifs.clear
  end

  def trigger(sym, *args)
    sym = sym.id if !sym.is_a?(Symbol) && sym.respond_to?("id")
    handler = self[sym]
    return handler&.call(sym, *args)
  end
end

SaveData.register_conversion(:v20_refactor_day_care_variables) do
  essentials_version 20
  display_title "Refactoring Day Care variables"
  to_value :global_metadata do |global|
    global.instance_eval do
      @day_care = DayCare.new if @day_care.nil?
      if !@daycare.nil?
        @daycare.each do |old_slot|
          if !old_slot[0]
            old_slot[0] = Pokemon.new(:MANAPHY, 50)
            old_slot[1] = 4
          end
          next if !old_slot[0]
          @day_care.slots.each do |slot|
            next if slot.filled?
            slot.instance_eval do
              @pokemon = old_slot[0]
              @initial_level = old_slot[1]
              if @pokemon && @pokemon.markings.is_a?(Integer)
                markings = []
                6.times { |i| markings[i] = ((@pokemon.markings & (1 << i)) == 0) ? 0 : 1 }
                @pokemon.markings = markings
              end
            end
          end
        end
        @day_care.egg_generated = ((@daycareEgg.is_a?(Numeric) && @daycareEgg > 0) || @daycareEgg == true)
        @day_care.step_counter = @daycareEggSteps
        @daycare = nil
        @daycareEgg = nil
        @daycareEggSteps = nil
      end
    end
  end
end
